                    "sql": "CREATE TABLE IF NOT EXISTS public.shipment_status_mapping ( SHIPPING_STATUS VARCHAR(256), Mapped_Status VARCHAR(256) ); DELETE FROM public.shipment_status_mapping; INSERT INTO public.shipment_status_mapping VALUES (\'DELIVERED\',\'Delivered\'),(\'CANCELLED\',\'Cancelled\'),(\'DELIVERED TO ORIGIN\',\'Returned\'),(\'SHIPMENT CREATED\',\'Shipment Created\'), (\'RETURNED\',\'Returned\'),(\'IN TRANSIT\',\'In Transit\'),(\'DELIVERY DELAYED\',\'In Transit\'),(\'CONFIRMED\',\'Open\'), (\'IN_TRANSIT\',\'In Transit\'),(\'RTO DELIVERED\',\'RTO\'),(\'CANCELED\',\'Cancelled\'),(\'RTO IN TRANSIT\',\'RTO\'), (\'REACHED AT DESTINATION HUB\',\'In Transit\'),(\'PICKED UP\',\'In Transit\'),(\'UNDELIVERED-2ND ATTEMPT\',\'In Transit\'), (\'RTO_OFD\',\'RTO\'),(\'OUT FOR DELIVERY\',\'Out for delivery\'),(\'RTO INITIATED\',\'RTO\'),(\'PICKUP EXCEPTION\',\'Pickup Error\'), (\'CANCELLATION REQUESTED\',\'Pickup Error\'),(\'READY TO SHIP\',\'Ready to Ship\'),(\'OUT_FOR_DELIVERY\',\'Out for delivery\'), (\'SHIPPED\',\'In Transit\'),(\'PICKUP RESCHEDULED\',\'Pickup Error\'),(\'UNDELIVERED-3RD ATTEMPT\',\'In Transit\'), (\'MISROUTED\',\'Misrouted\'),(\'PICKUP SCHEDULED\',\'Pickup Error\'),(\'UNDELIVERED-1ST ATTEMPT\',\'In Transit\'), (\'Not Traceble\',\'Pickup Error\'),(\'UNDELIVERED\',\'In Transit\'),(\'LOST\',\'Lost\'),(\'IN TRANSIT-EN-ROUTE\',\'In Transit\'), (\'Indian Speed Post\',\'Indian Speed Post\'),(\'Exception\',\'Exception\'),(\'Shipment Booked\',\'Pickup Error\'), (\'Assigned\',\'Assigned\'),(\'Pending\',\'Pending\'),(\'PrINT\',\'PrINT\'),(\'IN TRANSIT-AT DESTINATION HUB\',\'In Transit\'), (\'Upcoming\',\'Order Yet To sync\'),(\'RTO-In Transit\',\'RTO\'),(\'PICKUP ERROR\',\'Pickup Error\'),(\'RTO-Out for Delivery\',\'RTO\'), (\'RTO-Delivered\',\'RTO\'),(\'OUT FOR PICKUP\',\'Pickup Error\'),(\'RTO_NDR\',\'RTO\'),(\'RTO-Exception\',\'Exception\'), (\'Delayed\',\'In Transit\'),(\'IN TRANSIT-AT SOURCE HUB\',\'In Transit\'),(\'RTS\',\'Underprocess\'),(\'Manifested\',\'Pickup Error\'), (\'Dispatched\',\'In Transit\'),(\'RTO\',\'RTO\'),(\'Not Picked\',\'Pickup Error\'),(\'DAMAGED\',\'Damaged\'),(\'Closed\',\'Cancelled\'), (\'Open\',\'Open\'),(\'On Hold\',\'On Hold\'),(\'Shipped - Returned to Seller\',\'RTO\'),(\'Shipped - Delivered to Buyer\',\'Delivered\'), (\'Shipped - Picked Up\',\'In Transit\'),(\'Shipped - Rejected by Buyer\',\'RTO\'),(\'Shopify_Processed\',\'Shopify_Processed\'), (\'Ready to dispatch\',\'Ready to Dispatch\'),(\'RTO Undelivered\',\'RTO\'),(\'Shipment Lost\',\'Lost\'),(\'Shipment Error\',\'Shipment Error\'), (\'RTO In-Transit\',\'RTO\'),(\'Dispatch / RTO\',\'RTO\'),(\'Pending Pick-up\',\'Pending\'),(\'Dispatch/Intransit\',\'In Transit\'), (\'Dispatch /Lost and Damange\',\'Lost\'),(\'Dispatch /Undelivered\',\'Undelivered\'),(\'Non serviceable\',\'Non Serviceable\'), (\'Not serviceable\',\'Non Serviceable\'),(\'Dispatch/Delivered\',\'Delivered\'),(\'Refund\',\'Refund\'),(\'F&P\',\'F&P\'), (\'SHIPPED - RETURNING TO SELLER\',\'RTO\'),(\'SHIPPED - LOST IN TRANSIT\',\'Lost\'),(\'SHIPPED - DAMAGED\',\'Damaged\'), (\'SHIPPED - OUT FOR DELIVERY\',\'Out for delivery\'); CREATE TABLE IF NOT EXISTS public.facility_pincode ( facility VARCHAR(256), pincode VARCHAR(20) ); drop table if exists public.quickshift_sales_consolidated; CREATE TABLE public.quickshift_sales_consolidated AS SELECT NULL::VARCHAR(256) AS customer_id, UPPER(marketplace) AS SHOP_NAME, UPPER(marketplace) AS marketplace, UPPER(marketplace) AS CHANNEL, UPPER(marketplace) AS SOURCE, order_id, reference_code, NULL::VARCHAR(256) AS tags, PHONE, NAME, email, CAST(shipping_last_update_date AS TIMESTAMP) AS SHIPPING_LAST_UPDATE_DATE, Marketplace_sku, PRODUCT_ID, UPPER(PRODUCT_NAME) AS PRODUCT_NAME, CURRENCY, UPPER(CITY) AS City, UPPER(STATE) AS State, UPPER(ORDER_STATUS) AS Order_Status, CAST(CAST(ORDER_DATE AS TIMESTAMP) AS DATE) AS Order_Date, CAST(ORDER_DATE AS TIMESTAMP) AS ORDER_TIME, SUBORDER_QUANTITY AS QUANTITY, COALESCE(SELLING_PRICE, 0) - COALESCE(tax, 0) + COALESCE(DISCOUNT, 0) AS GROSS_SALES_BEFORE_TAX, DISCOUNT, TAX, SHIPPING_PRICE, SELLING_PRICE, UPPER(ORDER_STATUS) AS OMS_Order_Status, UPPER(b.Shipping_status) AS SHIPPING_STATUS, UPPER(COALESCE(shipmap.final_shipping_status, b.shipping_status)) AS FINAL_SHIPPING_STATUS, SaleOrderItemCode AS SALEORDERITEMCODE, SaleOrderItemCode AS SALES_ORDER_ITEM_ID, AWB, NULL::VARCHAR(256) AS Payment_Gateway, payment_mode AS Payment_Mode, UPPER(COURIER) AS COURIER, CAST(dispatch_DATE AS TIMESTAMP) AS DISPATCH_DATE, CAST(delivery_date AS TIMESTAMP) AS DELIVERED_DATE, CASE WHEN LOWER(COALESCE(ShipMap.shipping_status, b.shipping_status)) = \'delivered\' THEN 1 ELSE 0 END AS DELIVERED_STATUS, RETURN_FLAG, CASE WHEN RETURN_FLAG = 1 THEN CAST(suborder_quantity AS BIGINT) END AS returned_quantity, CASE WHEN RETURN_FLAG = 1 AND LOWER(order_status) NOT IN (\'cancelled\') THEN COALESCE(RETURN_FLAG, 0) END AS returned_sales, CASE WHEN RETURN_FLAG = 0 AND LOWER(order_status) IN (\'cancelled\') THEN CAST(suborder_quantity AS BIGINT) END AS cancelled_quantity, null::VARCHAR(256) AS NEW_CUSTOMER_FLAG, NULL::VARCHAR(256) AS ACQUISITION_PRODUCT, NULL::VARCHAR(256) AS ACQUISITION_CHANNEL, NULL::VARCHAR(256) AS ACQUISITION_MARKETPLACE, CASE WHEN LOWER(COALESCE(shipmap.final_shipping_status, b.shipping_status)) IN (\'delivered\', \'delivered to origin\') THEN DATEDIFF(day, CAST(ORDER_DATE AS DATE), CURRENT_DATE) WHEN LOWER(COALESCE(shipmap.final_shipping_status, b.shipping_status)) IN (\'in transit\', \'shipment created\') THEN DATEDIFF(day, CAST(ORDER_DATE AS DATE), CURRENT_DATE) END AS DAYS_IN_SHIPMENT, NULL::DATE AS ACQUISITION_DATE, SKU AS SKU_CODE, UPPER(product_name) AS PRODUCT_NAME_FINAL, category AS PRODUCT_CATEGORY, null::varchar(256) AS PRODUCT_SUB_CATEGORY, CASE WHEN sku = \'\' THEN NULL ELSE sku END AS commonsku, UPPER(WAREHOUSE_NAME) AS WAREHOUSE, shipping_pincode as pincode, null::varchar(256) as pickup_pincode, NULL::VARCHAR(256) AS Source_name, NULL::VARCHAR(256) AS Mapped_Source_Name, NULL::VARCHAR(256) AS Order_Type, invoice_date::timestamp as invoice_date, NULL::DATE AS refund_date_final, NULL::NUMERIC AS refund_value, NULL::TIMESTAMP AS cancelled_at, NULL as customer_id_final, null as source_pincode, shippingPackageStatus::varchar as shippingPackageStatus, shipping_tracking_status::varchar as shipping_tracking_status, shipping_package_creation_date::timestamp as shipping_package_creation_date, \'UNICOMMERCE\' as data_source FROM public.QUICKSHIFT_UNICOMMERCE_FACT_ITEMS b LEFT JOIN ( SELECT * FROM ( SELECT UPPER(Shipping_status) AS shipping_status, UPPER(mapped_status) AS final_shipping_status, ROW_NUMBER() OVER (PARTITION BY LOWER(shipping_Status) ORDER BY 1) AS rw FROM public.shipment_status_mapping ) shipmap WHERE shipmap.rw = 1 ) ShipMap ON LOWER(COALESCE(b.shipping_status, b.order_status)) = LOWER(ShipMap.shipping_status) UNION ALL SELECT NULL::VARCHAR(256) AS customer_id, UPPER(SHOP_NAME) AS SHOP_NAME, UPPER(marketplace) AS marketplace, UPPER(marketplace) AS CHANNEL, UPPER(marketplace) AS SOURCE, ORDER_ID, reference_code, NULL::VARCHAR(256) AS tags, contact_num AS PHONE, customer_name AS NAME, email AS EMAIL, CAST(shipping_last_update_date AS TIMESTAMP) AS SHIPPING_LAST_UPDATE_DATE, SKU, PRODUCT_ID, UPPER(PRODUCTNAME) AS PRODUCT_NAME, CURRENCY, UPPER(CITY) AS City, UPPER(STATE) AS State, UPPER(ORDER_STATUS) AS Order_Status, CAST(CAST(ORDER_DATE AS TIMESTAMP) AS DATE) AS Order_Date, CAST(ORDER_DATE AS TIMESTAMP) AS ORDER_TIMESTAMP, SUBORDER_QUANTITY AS QUANTITY, COALESCE(SELLING_PRICE, 0) - COALESCE(tax, 0) + COALESCE(DISCOUNT, 0) AS GROSS_SALES_BEFORE_TAX, DISCOUNT, TAX, SHIPPING_PRICE, SELLING_PRICE, UPPER(ORDER_STATUS) AS OMS_Order_Status, UPPER(b.Shipping_status) AS SHIPPING_STATUS, UPPER(COALESCE(shipmap.final_shipping_status, b.shipping_status)) AS FINAL_SHIPPING_STATUS, Marketplace_LineItem_ID AS SALEORDERITEMCODE, suborder_id AS SALES_ORDER_ITEM_ID, AWB, NULL::VARCHAR(256) AS Payment_Gateway, payment_mode AS Payment_Mode, UPPER(COURIER) AS COURIER, CAST(MANIFEST_DATE AS TIMESTAMP) AS DISPATCH_DATE, CAST(DELIVERED_DATE AS TIMESTAMP) AS DELIVERED_DATE, CASE WHEN LOWER(COALESCE(ShipMap.shipping_status, b.shipping_status)) = \'delivered\' THEN 1 ELSE 0 END AS DELIVERED_STATUS, IS_REFUND AS RETURN_FLAG, CASE WHEN is_refund = 1 THEN CAST(suborder_quantity AS BIGINT) END AS returned_quantity, CASE WHEN is_refund = 1 AND LOWER(order_status) NOT IN (\'cancelled\') THEN COALESCE(is_refund, 0) END AS returned_sales, CASE WHEN is_refund = 0 AND LOWER(order_status) IN (\'cancelled\') THEN CAST(suborder_quantity AS BIGINT) END AS cancelled_quantity, CAST(new_customer_flag AS VARCHAR(256)) AS NEW_CUSTOMER_FLAG, NULL::VARCHAR(256) AS ACQUISITION_PRODUCT, NULL::VARCHAR(256) AS ACQUISITION_MARKETPLACE, NULL::VARCHAR(256) AS ACQUISITION_channel, CAST(Days_in_shipment AS BIGINT) AS DAYS_IN_SHIPMENT, NULL::DATE AS ACQUISITION_DATE, SKU AS SKU_CODE, UPPER(mapped_product_name) AS PRODUCT_NAME_FINAL, UPPER(mapped_category) AS PRODUCT_CATEGORY, null::varchar(256) AS PRODUCT_SUB_CATEGORY, COALESCE(CASE WHEN b.commonsku = \'\' THEN NULL ELSE b.commonsku END, b.master_SKU) AS commonsku, UPPER(WAREHOUSE_NAME) AS WAREHOUSE, pincode, pickup_pincode, NULL::VARCHAR(256) AS Source_name, NULL::VARCHAR(256) AS Mapped_Source_Name, NULL::VARCHAR(256) AS Order_Type, b.invoice_date::timestamp as invoice_date, NULL::DATE AS refund_date_final, NULL::NUMERIC AS refund_value, NULL::TIMESTAMP AS cancelled_at, NULL as customer_id_final, null as source_pincode, NULL::VARCHAR as shippingPackageStatus, NULL::VARCHAR as shipping_tracking_status, NULL::TIMESTAMP as shipping_package_creation_date, \'EASYECOM\' as data_source FROM public.QUICKSHIFT_EASYECOM_FACT_ITEMS b LEFT JOIN ( SELECT * FROM ( SELECT UPPER(Shipping_status) AS shipping_status, UPPER(mapped_status) AS final_shipping_status, ROW_NUMBER() OVER (PARTITION BY LOWER(shipping_Status) ORDER BY 1) AS rw FROM public.shipment_status_mapping ) shipmap WHERE shipmap.rw = 1 ) ShipMap ON LOWER(COALESCE(b.shipping_status, b.order_status)) = LOWER(ShipMap.shipping_status) ; DROP TABLE IF EXISTS public.GS_State_ISO; CREATE TABLE public.GS_State_ISO ( state VARCHAR(256), iso_code VARCHAR(10) ); UPDATE public.quickshift_sales_consolidated SET state = CASE WHEN UPPER(state) IN (\'AP\', \'ANDHRA PRADESH\', \'ANDHRAPRADESH\') THEN \'ANDHRA PRADESH\' WHEN UPPER(state) IN (\'AR\', \'ARUNACHAL PRADESH\') THEN \'ARUNACHAL PRADESH\' WHEN UPPER(state) IN (\'AS\', \'ASSAM\', \'ASSAM HINDUISM\') THEN \'ASSAM\' WHEN UPPER(state) IN (\'BR\', \'BIHAR\') THEN \'BIHAR\' WHEN UPPER(state) IN (\'CT\', \'CHHATTISGARH\', \'CHATTISGARH\', \'CHHATISGARH\') THEN \'CHHATTISGARH\' WHEN UPPER(state) IN (\'GA\', \'GOA\') THEN \'GOA\' WHEN UPPER(state) IN (\'GJ\', \'GUJARAT\', \'GUJRAT\') THEN \'GUJARAT\' WHEN UPPER(state) IN (\'HR\', \'HARYANA\') THEN \'HARYANA\' WHEN UPPER(state) IN (\'HP\', \'HIMACHAL PRADESH\', \'HIMANCHAL PRADESH\') THEN \'HIMACHAL PRADESH\' WHEN UPPER(state) IN (\'JH\', \'JHARKHAND\') THEN \'JHARKHAND\' WHEN UPPER(state) IN (\'KA\', \'KARNATAKA\', \'KARANATAKA\', \'KARNATKA\') THEN \'KARNATAKA\' WHEN UPPER(state) IN (\'KL\', \'KERALA\') THEN \'KERALA\' WHEN UPPER(state) IN (\'MP\', \'MADHYA PRADESH\', \'MADHYAPRADESH\', \'M. P\') THEN \'MADHYA PRADESH\' WHEN UPPER(state) IN (\'MH\', \'MAHARASHTRA\', \'MAHARASTRA\', \'MAHARASHATRA\', \'MAHASHTRA\', \'MUMBAI THANA\') THEN \'MAHARASHTRA\' WHEN UPPER(state) IN (\'MN\', \'MANIPUR\') THEN \'MANIPUR\' WHEN UPPER(state) IN (\'ML\', \'MEGHALAYA\', \'MEGALAYA\') THEN \'MEGHALAYA\' WHEN UPPER(state) IN (\'MZ\', \'MIZORAM\') THEN \'MIZORAM\' WHEN UPPER(state) IN (\'NL\', \'NAGALAND\') THEN \'NAGALAND\' WHEN UPPER(state) IN (\'OR\', \'ODISHA\', \'ORISSA\') THEN \'ODISHA\' WHEN UPPER(state) IN (\'PB\', \'PUNJAB\') THEN \'PUNJAB\' WHEN UPPER(state) IN (\'RJ\', \'RAJASTHAN\') THEN \'RAJASTHAN\' WHEN UPPER(state) IN (\'SK\', \'SIKKIM\') THEN \'SIKKIM\' WHEN UPPER(state) IN (\'TN\', \'TAMIL NADU\', \'TAMILNADU\') THEN \'TAMIL NADU\' WHEN UPPER(state) IN (\'TS\', \'TL\', \'TELANGANA\') THEN \'TELANGANA\' WHEN UPPER(state) IN (\'TR\', \'TRIPURA\') THEN \'TRIPURA\' WHEN UPPER(state) IN (\'UP\', \'UTTAR PRADESH\', \'UTTER PRADESH\') THEN \'UTTAR PRADESH\' WHEN UPPER(state) IN (\'UT\', \'UK\', \'UTTARAKHAND\', \'UTTRAKHAND\') THEN \'UTTARAKHAND\' WHEN UPPER(state) IN (\'WB\', \'WEST BENGAL\', \'WEST BANGAL\', \'WB(KOLKATA & HOWRAH AREA)\') THEN \'WEST BENGAL\' WHEN UPPER(state) IN (\'AN\', \'ANDAMAN AND NICOBAR ISLANDS\', \'ANDAMAN & NICOBAR ISLANDS\') THEN \'ANDAMAN AND NICOBAR ISLANDS\' WHEN UPPER(state) IN (\'CH\', \'CHANDIGARH\') THEN \'CHANDIGARH\' WHEN UPPER(state) IN (\'DN\', \'DADRA AND NAGAR HAVELI\', \'DADRA & NAGAR HAVELI\', \'DD\', \'DAMAN AND DIU\', \'DAMAN & DIU\', \'DADRA & NAGAR HAVELI AND DAMAN & DIU\', \'DADRA AND NAGAR HAVELI AND DAMAN AND DIU\', \'DADRA AND NAGAR HAV.\') THEN \'DADRA AND NAGAR HAVELI AND DAMAN AND DIU\' WHEN UPPER(state) IN (\'LD\', \'LAKSHADWEEP\') THEN \'LAKSHADWEEP\' WHEN UPPER(state) IN (\'DL\', \'DELHI\', \'NEW DELHI\', \'NCR\') THEN \'DELHI\' WHEN UPPER(state) IN (\'PY\', \'PUDUCHERRY\', \'PONDICHERRY\') THEN \'PUDUCHERRY\' WHEN UPPER(state) IN (\'JK\', \'JAMMU AND KASHMIR\', \'JAMMU & KASHMIR\') THEN \'JAMMU AND KASHMIR\' WHEN UPPER(state) = \'LADAKH\' THEN \'LADAKH\' WHEN UPPER(state) IN (\'AUCKLAND\', \'UNITED KINGDOM (+44)\', \'NON-US\', \'ZEELAND\', \'SINGAPORE\', \'BARCELONA\') THEN NULL WHEN UPPER(state) IN (\'INDIA\', \'1493\', \'BJP.TEAM211@GMAIL.COM\') THEN NULL WHEN UPPER(state) IN (\'NOT SPECIFIED\', \'\') THEN NULL ELSE state END;",
